<script lang="ts">
  import { invalidateAdminCache, watchAdminQuery } from '$lib/admin/client';
 import { onMount } from 'svelte';import { adminRequest } from '$lib/admin/client';import ConfirmDialog from '$lib/components/admin/ConfirmDialog.svelte';
 let result=$state<any>({items:[],total:0}),page=$state(1),action=$state(''),status=$state(''),targetId=$state(''),busy=$state(false),problem=$state(''),retryId=$state(''),password=$state('');
 let sequence=0;
 let activeQuery=$state('');
 $effect(()=>activeQuery ? watchAdminQuery<any>(activeQuery,next=>{result=next;}) : undefined);
 async function load(reset=false){if(reset)page=1;const request=++sequence;busy=true;problem='';try{activeQuery=`api/audit?${new URLSearchParams({page:String(page),pageSize:'20',action:action==='login'?'login_success':action,status,targetId})}`;const response=await adminRequest(activeQuery);if(request===sequence)result=response;}catch(e){if(request===sequence)problem=(e as Error).message;}finally{if(request===sequence)busy=false;}}
 async function retry(){busy=true;try{await adminRequest('reauth',{password});password='';await adminRequest(`api/operations/${retryId}/retry`,{});retryId='';await load();}catch(e){problem=(e as Error).message;retryId='';}finally{busy=false;password='';}}
 onMount(()=>load());
</script>
<h1>Audit log</h1><form class="toolbar" onsubmit={e=>{e.preventDefault();load(true);}}><label>Action <select bind:value={action}><option value="">All</option><option value="delete_attempts">Exam deletion</option><option value="reset">Progress reset</option><option value="delete_account">Account deletion</option><option value="login">Login</option><option value="logout">Logout</option></select></label><label>Status <select bind:value={status}><option value="">All</option><option value="succeeded">Succeeded</option><option value="complete">Complete</option><option value="auth_delete_failed">Deletion failed</option><option value="auth_delete_pending">Deletion pending</option></select></label><label>Target user ID <input bind:value={targetId}/></label><button class="btn-primary" disabled={busy}>Filter</button><button class="btn-ghost" type="button" disabled={busy} onclick={()=>{invalidateAdminCache('api/audit?');load();}}>Refresh</button></form>
{#if problem}<p class="error" role="alert">{problem}</p>{/if}<div class="admin-card"><div class="table-scroll"><table><thead><tr><th>Time</th><th>Actor / target</th><th>Action</th><th>Count / result</th><th></th></tr></thead><tbody>{#each result.items as row}<tr><td>{new Date(row.createdAt??row.created_at).toLocaleString()}</td><td><small>{row.actorId??row.actor_id??'System'}<br/>{row.targetId??row.target_id??'None'}</small></td><td>{row.action}<br/><small>{row.operationId??row.operation_id??''}</small></td><td>{row.count??0} · {row.operationStatus??row.status}</td><td>{#if (row.operationId||row.operation_id)&&['auth_delete_pending','auth_delete_failed','app_data_removed','prepared'].includes(row.operationStatus??row.status)}<button class="btn-ghost" onclick={()=>retryId=row.operationId??row.operation_id}>Retry account deletion</button>{/if}</td></tr>{:else}<tr><td colspan="5">{busy?'Loading…':'No matching actions.'}</td></tr>{/each}</tbody></table></div><div class="pagination"><button class="btn-ghost" disabled={page<=1||busy} onclick={()=>{page--;load();}}>Previous</button><span>Page {page}</span><button class="btn-ghost" disabled={page*20>=result.total||busy} onclick={()=>{page++;load();}}>Next</button></div></div>
{#if retryId}<ConfirmDialog title="Retry account deletion" {busy} onClose={()=>retryId=''}><p>This resumes the same deletion operation. It does not restore removed data.</p><form onsubmit={e=>{e.preventDefault();retry();}}><label>Your administrator password <input type="password" autocomplete="current-password" bind:value={password} required/></label><div class="toolbar"><button type="button" class="btn-ghost" disabled={busy} onclick={()=>retryId=''}>Cancel</button><button class="danger" disabled={busy||!password}>Reauthenticate and retry</button></div></form></ConfirmDialog>{/if}
